import createClient, { type Client, type Middleware } from 'openapi-fetch';
import { HubApiError } from './errors';
import type { paths } from './schema';

/**
 * The single entry point for `/admin/v1` (AGENTS.md: all calls go through here).
 * Types come from `schema.d.ts`, generated by `npm run gen:api` from the frozen contract.
 */

/**
 * Response header carrying the Hub request id (`req_` + ULID). hub-admin declares it on every
 * response, success or error, since 1.1.0 (`components.headers.X-Hub-Request-Id`, CCR-001,
 * HUB-278). Successes carry it as `requestId`; on errors it equals `error.request_id`, and the
 * body's `request_id` still wins when both are present (see `HubApiError.fromResponse`).
 */
export const REQUEST_ID_HEADER = 'X-Hub-Request-Id';

/**
 * Concurrency token of live objects (tenants, registrar endpoints, ...; contract
 * `components.headers.ETag`). Sent back as `If-Match` on PATCH, which answers 412
 * `PRECONDITION_FAILED` when someone else changed the object first (HUB-270).
 */
export const ETAG_HEADER = 'ETag';

/** Default base when `PUBLIC_ADMIN_API_BASE` is not set: the admin API on the console's origin. */
export const DEFAULT_ADMIN_API_BASE = '/admin/v1';

export type AdminPaths = paths;
export type RawAdminClient = Client<paths>;

export type ApiResult<T> =
	| { ok: true; data: T; status: number; requestId: string | null; etag: string | null }
	| { ok: false; error: HubApiError; status: number; requestId: string | null };

/** Shape every openapi-fetch method resolves to. */
type FetchResult = { data?: unknown; error?: unknown; response: Response };

/** The success body type of an openapi-fetch result union (the member whose `data` is required). */
export type SuccessData<R> = R extends { data: infer D; error?: never } ? D : never;

export interface AdminClientOptions {
	/** Absolute or origin-relative base, e.g. `https://hub-admin.staging.internal/admin/v1`. */
	baseUrl?: string;
	/** Origin used to resolve a relative `baseUrl` (pass `event.url.origin` on the server). */
	origin?: string;
	/** Use the `fetch` SvelteKit hands to `load`/actions so SSR dedupes and cookies flow. */
	fetch?: typeof fetch;
	/** OIDC access token, server side only. Never keep it in browser storage. */
	token?: string | (() => string | null | undefined);
}

export interface AdminClient {
	/** The typed openapi-fetch client (auth middleware installed). Prefer `call`. */
	readonly raw: RawAdminClient;
	/** Runs one typed request and normalises the outcome into an `ApiResult`. Never throws. */
	call<R extends FetchResult>(
		fn: (c: RawAdminClient) => Promise<R>
	): Promise<ApiResult<SuccessData<R>>>;
}

export function resolveBaseUrl(baseUrl: string, origin?: string): string {
	if (/^https?:\/\//i.test(baseUrl)) return baseUrl.replace(/\/+$/, '');
	const from = origin ?? globalThis.location?.origin ?? 'http://localhost';
	return new URL(baseUrl, from).toString().replace(/\/+$/, '');
}

export function adminClient(opts: AdminClientOptions = {}): AdminClient {
	const raw = createClient<paths>({
		baseUrl: resolveBaseUrl(opts.baseUrl ?? DEFAULT_ADMIN_API_BASE, opts.origin),
		fetch: opts.fetch
	});

	const auth: Middleware = {
		onRequest({ request }) {
			const token = typeof opts.token === 'function' ? opts.token() : opts.token;
			if (token) request.headers.set('Authorization', `Bearer ${token}`);
			return request;
		}
	};
	raw.use(auth);

	async function call<R extends FetchResult>(
		fn: (c: RawAdminClient) => Promise<R>
	): Promise<ApiResult<SuccessData<R>>> {
		let r: R;
		try {
			r = await fn(raw);
		} catch (cause) {
			const error = HubApiError.network(cause);
			return { ok: false, error, status: 0, requestId: null };
		}
		const { response } = r;
		// Declared on every admin response (hub-admin 1.1.0); null only if a proxy dropped it.
		const headerRequestId = response.headers.get(REQUEST_ID_HEADER) || null;
		if (response.ok) {
			return {
				ok: true,
				data: r.data as SuccessData<R>,
				status: response.status,
				requestId: headerRequestId,
				etag: response.headers.get(ETAG_HEADER) || null
			};
		}
		const error = HubApiError.fromResponse(r.error, response, headerRequestId);
		return { ok: false, error, status: response.status, requestId: error.requestId };
	}

	return { raw, call };
}

/** Returns the data or throws the `HubApiError` (handy in `load`, where SvelteKit maps throws). */
export function unwrap<T>(result: ApiResult<T>): T {
	if (result.ok) return result.data;
	throw result.error;
}
